// Generated by tools-common/claudeplugin. Do not edit: regenerate instead.
//
// Runs `BIN watch` for the whole session and starts a turn with each event it
// prints. The binary decides what each event says and whether this session
// hears anything; this mod only carries its lines:
//   {"text": ...}   submit text, word for word
//   {"stop": ...}   log the reason; watch exits and is not restarted

const NAME = "muster"
const BIN = "muster"

// Claude Code's own words for a prompt it refused or dropped; such a prompt is
// kept and submitted again from turn.complete.
const RETRY = [
  'the session was stopped and nobody has sent input since',
  'was removed from the queue before it ran',
]

// Restart delay after watch ends: doubles up to the cap, back to the start
// once watch prints an event.
const FIRST_DELAY = 2000
const MAX_DELAY = 60000

let pending = []
let generation = 0
let current = null
let delay = FIRST_DELAY

async function submitPrompt($, text) {
  let reason
  try {
    const result = await $.prompt.submit({ text })
    reason = result?.drop ?? ''
  } catch (error) {
    reason = String(error?.message ?? error)
  }
  if (RETRY.some(s => reason.includes(s))) pending.push(text)
  else if (reason) $.ui.log(NAME + ' event not delivered: ' + reason)
}

async function watch($, gen) {
  let ended = 'ended'
  try {
    const id = await $.session.id()
    if (gen !== generation) return
    const child = $.process.spawn({ argv: [BIN, 'watch'], env: { CLAUDE_CODE_SESSION_ID: id } })
    current = child
    let buf = ''
    for await (const { stream, text } of child) {
      if (gen !== generation) return
      if (stream !== 'stdout') continue
      buf += text
      let i
      while ((i = buf.indexOf('\n')) >= 0) {
        const line = buf.slice(0, i).trim()
        buf = buf.slice(i + 1)
        if (!line) continue
        let ev
        try {
          ev = JSON.parse(line)
        } catch {
          $.ui.log(BIN + ' watch printed a line that is not JSON: ' + line.slice(0, 200), { to: 'debug' })
          continue
        }
        if (typeof ev?.stop === 'string') {
          $.ui.log(BIN + ' watch stopped: ' + ev.stop, { to: 'debug' })
          return
        }
        if (typeof ev?.text !== 'string') {
          $.ui.log(BIN + ' watch printed a line with no text: ' + line.slice(0, 200), { to: 'debug' })
          continue
        }
        delay = FIRST_DELAY
        // Not awaited: submit waits until the session is idle.
        void submitPrompt($, ev.text)
      }
    }
    const r = await child.result
    ended = r.signal ? 'ended (' + r.signal + ')' : 'exited with code ' + r.code
  } catch (error) {
    ended = 'failed: ' + String(error?.message ?? error)
  }
  if (gen !== generation) return
  $.ui.log(BIN + ' watch ' + ended + '; restarting in ' + Math.round(delay / 1000) + 's')
  $.clock.after(delay, () => {
    if (gen === generation) void watch($, gen)
  })
  delay = Math.min(delay * 2, MAX_DELAY)
}

function start($) {
  // session.start runs again on hot reload and /clear: one reader at a time.
  generation += 1
  const old = current
  current = null
  if (old) {
    try {
      void old.return()
    } catch {}
  }
  delay = FIRST_DELAY
  void watch($, generation)
}

export function register(on) {
  on('session.start', async ($, e, next) => {
    const started = await next(e)
    start($)
    return started
  })

  on('turn.complete', async ($, e, next) => {
    if (pending.length) {
      const texts = pending
      // Emptied first, so a second run of this hook doesn't submit them twice.
      pending = []
      for (const text of texts) void submitPrompt($, text)
    }
    return next(e)
  })
}
